{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The ALB listener is configured to use HTTP protocol, which is insecure and can expose data to eavesdropping."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "Ensure that load balancer is using at least TLS 1.2",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The ALB listener is not configured to use HTTPS protocol, making it impossible to enforce a minimum TLS version."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-TLS-1-2-Ext-2018-06\"\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}",
  "fix_summary": "Changed the ALB listener protocol to HTTPS, updated the port to 443, and set the ssl_policy to ELBSecurityPolicy-TLS-1-2-Ext-2018-06 to ensure TLS 1.2 is used."
}
